#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 998244353;

int main(){
    int n;
    if(scanf("%d",&n)!=1) return 0;
    vector<int> head(n+1,-1);
    vector<int> nxt(2*(n>1?n-1:1)+2), to(2*(n>1?n-1:1)+2);
    int cnt=0;
    for(int i=0;i<n-1;i++){
        int u,v; scanf("%d %d",&u,&v);
        to[cnt]=v; nxt[cnt]=head[u]; head[u]=cnt++;
        to[cnt]=u; nxt[cnt]=head[v]; head[v]=cnt++;
    }
    vector<int> order; order.reserve(n);
    vector<int> par(n+1,0);
    vector<char> vis(n+1,0);
    {
        vector<int> stk;
        stk.push_back(1); vis[1]=1; par[1]=0;
        while(!stk.empty()){
            int v=stk.back(); stk.pop_back();
            order.push_back(v);
            for(int e=head[v]; e!=-1; e=nxt[e]){
                int u=to[e];
                if(!vis[u]){ vis[u]=1; par[u]=v; stk.push_back(u); }
            }
        }
    }
    vector<ll> s0(n+1,0), s1(n+1,1), s2(n+1,0);
    for(int i=(int)order.size()-1;i>=1;i--){
        int v=order[i];
        int p=par[v];
        ll K=(s0[v]+s1[v])%MOD;
        ll P=s0[v]%MOD;
        ll M=(s1[v]+s2[v])%MOD;
        ll KP=(K+P)%MOD;
        ll n0=(s0[p]*KP + ((s1[p]+s2[p])%MOD)*M)%MOD;
        ll n1=(s1[p]*K)%MOD;
        ll n2=(s1[p]*P + s2[p]*KP)%MOD;
        s0[p]=n0; s1[p]=n1; s2[p]=n2;
    }
    ll ans=(s0[1]+s1[1])%MOD;
    printf("%lld\n", ans);
    return 0;
}
