#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;
const ull MOD = 1000000007ULL;

ull pw(ull b, ull e, ull m){
    ull r = 1 % m;
    b %= m;
    while(e){
        if(e & 1) r = r * b % m;
        b = b * b % m;
        e >>= 1;
    }
    return r;
}

int main(){
    ull x, n;
    if(!(cin >> x >> n)) return 0;
    vector<ull> primes;
    ull t = x;
    for(ull p = 2; p * p <= t; p++){
        if(t % p == 0){
            primes.push_back(p);
            while(t % p == 0) t /= p;
        }
    }
    if(t > 1) primes.push_back(t);
    ull ans = 1;
    for(ull p : primes){
        ull total = 0;
        ull cur = p;
        while(true){
            total += n / cur;
            if(cur > n / p) break; // cur*p > n
            cur *= p;
        }
        ans = ans * pw(p % MOD, total, MOD) % MOD;
    }
    cout << ans << endl;
    return 0;
}
