#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    string s;
    if(!(cin >> n)) return 0;
    cin >> s;
    int m = s.size();

    // prefix function
    vector<int> pi(m, 0);
    for(int i = 1; i < m; i++){
        int j = pi[i-1];
        while(j > 0 && s[i] != s[j]) j = pi[j-1];
        if(s[i] == s[j]) j++;
        pi[i] = j;
    }

    // automaton: delta[i][c], i in 0..m-1, value in 0..m (m = accept)
    vector<array<int,2>> delta(m);
    for(int i = 0; i < m; i++){
        for(int c = 0; c < 2; c++){
            char ch = '0' + c;
            if(ch == s[i]) delta[i][c] = i + 1;
            else delta[i][c] = (i == 0) ? 0 : delta[pi[i-1]][c];
        }
    }

    long long total = 0;
    for(int start = 0; start < m; start++){
        vector<long long> dp(m, 0), nd(m, 0);
        dp[start] = 1;
        for(int step = 0; step < n; step++){
            for(int i = 0; i < m; i++) nd[i] = 0;
            for(int i = 0; i < m; i++){
                if(dp[i] == 0) continue;
                for(int c = 0; c < 2; c++){
                    int j = delta[i][c];
                    if(j < m) nd[j] += dp[i];
                }
            }
            dp.swap(nd);
        }
        total += dp[start];
    }

    long long all = 1LL << n;
    cout << (all - total) << endl;
    return 0;
}
