    ull p=1;
    while(true){ px.push_back(p); if(p> LIM/x) break; p*=x; }
    p=1;
    while(true){ py.push_back(p); if(p> LIM/y) break; p*=y; }
    vector<ull> v;
    for(ull a: px) for(ull b: py){
        if(a> LIM-b) continue;
        ull s=a+b;
        if(s>=l&&s<=r) v.push_back(s);
    }
    sort(v.begin(),v.end());
    v.erase(unique(v.begin(),v.end()),v.end());
    ull ans=0, prev=l;
    for(ull s: v){
        if(s>prev) ans=max(ans,s-prev);
        prev=s+1;
    }
    if(r+1>prev) ans=max(ans,r+1-prev);
    cout<<ans<<endl;
}
