ull powmod(ull a, ull e, ull m){ ull r=1; a%=m; while(e){ if(e&1) r=mulmod(r,a,m); a=mulmod(a,a,m); e>>=1;} return r;}
bool isprime(ull n){
    if(n<2) return false;
    for(ull p:{2ULL,3ULL,5ULL,7ULL,11ULL,13ULL,17ULL,19ULL,23ULL,29ULL,31ULL,37ULL}){
        if(n%p==0) return n==p;
    }
    ull d=n-1; int s=0; while(!(d&1)){d>>=1;s++;}
    for(ull a:{2ULL,3ULL,5ULL,7ULL,11ULL,13ULL,17ULL,19ULL,23ULL,29ULL,31ULL,37ULL}){
        ull x=powmod(a,d,n);
        if(x==1||x==n-1) continue;
        bool comp=true;
        for(int i=1;i<s;i++){ x=mulmod(x,x,n); if(x==n-1){comp=false;break;} }
        if(comp) return false;
    }
    return true;
}

