#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1000000007LL;

int main(){
    int n, k;
    if(scanf("%d %d", &n, &k)!=2) return 0;
    vector<ll> inv(n+2);
    inv[1]=1;
    for(int i=2;i<=n+1;i++){
        inv[i] = (MOD - (MOD/i) * inv[MOD%i] % MOD) % MOD;
    }
    vector<ll> h(n), P(n);
    h[0]=1; P[0]=1;
    for(int m=1;m<=n-1;m++){
        int lo = m-k; if(lo<0) lo=0;
        ll s = P[m-1];
        if(lo>0) s = (s - P[lo-1] % MOD + MOD) % MOD;
        h[m] = s % MOD * inv[m] % MOD;
        P[m] = (P[m-1] + h[m]) % MOD;
    }
    ll S = P[n-1];
    // factorials
    ll fact_nm1 = 1;
    for(int i=1;i<=n-1;i++) fact_nm1 = fact_nm1 * i % MOD;
    ll fact_n = fact_nm1 * (ll)n % MOD;
    ll correct = fact_nm1 * S % MOD;
    ll ans = (fact_n - correct % MOD + MOD) % MOD;
    printf("%lld\n", ans);
    return 0;
}
