int main(){
    long long n, m;
    scanf("%lld %lld", &n, &m);
    vector<long long> a(n);
    for(int i=0;i<n;i++) scanf("%lld",&a[i]);
    int n1 = n/2, n2 = n - n1;
    vector<long long> s1, s2;
    s1.reserve(1<<n1); s2.reserve(1<<n2);
    for(int mask=0; mask<(1<<n1); mask++){
        long long s=0;
        for(int i=0;i<n1;i++) if(mask&(1<<i)) s+=a[i];
        s1.push_back(s%m);
    }
    for(int mask=0; mask<(1<<n2); mask++){
        long long s=0;
        for(int i=0;i<n2;i++) if(mask&(1<<i)) s+=a[n1+i];
        s2.push_back(s%m);
    }
    sort(s2.begin(), s2.end());
    s2.erase(unique(s2.begin(), s2.end()), s2.end());
    long long best=0;
    for(size_t i=0;i<s1.size();i++){
        long long v = s1[i];
        // find largest x in s2 with x < m - v
        long long target = m - v;
        auto it = lower_bound(s2.begin(), s2.end(), target);
        if(it != s2.begin()){
            --it;
            best = max(best, (v + *it) % m);
        }
        best = max(best, (v + s2.back()) % m);
    }
    printf("%lld\n", best);
    return 0;
}
