#include <bits/stdc++.h>
using namespace std;

static int n, k;
static vector<int> A, par, order_, szv, downv, upv, startA, toA;
static vector<char> fullv, fullup, goodv;

bool check(int x) {
    for (int v = 1; v <= n; v++) goodv[v] = (A[v] >= x) ? 1 : 0;
    // pass 1: reverse order
    for (int i = n - 1; i >= 0; i--) {
        int v = order_[i];
        int s = 1, sumF = 0, maxNF = 0;
        bool isFull = true;
        for (int e = startA[v]; e < startA[v + 1]; e++) {
            int c = toA[e];
            if (c == par[v]) continue;
            s += szv[c];
            if (fullv[c]) sumF += szv[c];
            else { isFull = false; if (downv[c] > maxNF) maxNF = downv[c]; }
        }
        szv[v] = s;
        fullv[v] = (goodv[v] && isFull) ? 1 : 0;
        downv[v] = goodv[v] ? (1 + sumF + maxNF) : 0;
    }
    int root = order_[0];
    for (int i = 0; i < n; i++) {
        int p = order_[i];
        int sumF = 0, cntNF = 0, b1 = 0, i1 = -1, b2 = 0, i2 = -1;
        if (p != root) {
            if (fullup[p]) sumF += n - szv[p];
            else {
                cntNF++;
                int d = upv[p];
                if (d > b1) { b2 = b1; i2 = i1; b1 = d; i1 = 0; }
                else if (d > b2) { b2 = d; i2 = 0; }
            }
        }
        for (int e = startA[p]; e < startA[p + 1]; e++) {
            int c = toA[e];
            if (c == par[p]) continue;
            if (fullv[c]) sumF += szv[c];
            else {
                cntNF++;
                int d = downv[c];
                if (d > b1) { b2 = b1; i2 = i1; b1 = d; i1 = c; }
                else if (d > b2) { b2 = d; i2 = c; }
            }
        }
        (void)i2;
        int dpr = goodv[p] ? (1 + sumF + b1) : 0;
        if (dpr >= k) return true;
        for (int e = startA[p]; e < startA[p + 1]; e++) {
            int v = toA[e];
            if (v == par[p]) continue;
            int sf = sumF - (fullv[v] ? szv[v] : 0);
            int m = (i1 == v) ? b2 : b1;
            int nf = cntNF - (fullv[v] ? 0 : 1);
            upv[v] = goodv[p] ? (1 + sf + m) : 0;
            fullup[v] = (goodv[p] && nf == 0) ? 1 : 0;
        }
    }
    return false;
}

int main() {
    // fast input
    {
        static char buf[1 << 25];
        size_t len = fread(buf, 1, sizeof(buf) - 1, stdin);
        buf[len] = '\0';
        char *ptr = buf;
        auto readInt = [&]() -> int {
            while (*ptr && (*ptr < '0' || *ptr > '9')) ptr++;
            int r = 0;
            while (*ptr >= '0' && *ptr <= '9') { r = r * 10 + (*ptr - '0'); ptr++; }
            return r;
        };
        n = readInt(); k = readInt();
        A.assign(n + 1, 0);
        for (int i = 1; i <= n; i++) A[i] = readInt();
        vector<int> eu(n - 1), ev(n - 1);
        vector<int> deg(n + 2, 0);
        for (int i = 0; i < n - 1; i++) {
            int u = readInt(), v = readInt();
            eu[i] = u; ev[i] = v;
            deg[u]++; deg[v]++;
        }
        startA.assign(n + 2, 0);
        for (int i = 1; i <= n; i++) startA[i + 1] = startA[i] + deg[i];
        toA.assign(2 * (n - 1) > 0 ? 2 * (n - 1) : 1, 0);
        vector<int> pos(n + 2, 0);
        for (int i = 1; i <= n; i++) pos[i] = startA[i];
        for (int i = 0; i < n - 1; i++) {
            toA[pos[eu[i]]++] = ev[i];
            toA[pos[ev[i]]++] = eu[i];
        }
    }
    par.assign(n + 1, 0);
    order_.assign(n, 0);
    szv.assign(n + 1, 0);
    downv.assign(n + 1, 0);
    upv.assign(n + 1, 0);
    fullv.assign(n + 1, 0);
    fullup.assign(n + 1, 0);
    goodv.assign(n + 1, 0);

    // BFS order from node 1
    {
        int head = 0, tail = 0;
        order_[tail++] = 1;
        par[1] = 0;
        vector<char> vis(n + 1, 0);
        vis[1] = 1;
        while (head < tail) {
            int v = order_[head++];
            for (int e = startA[v]; e < startA[v + 1]; e++) {
                int c = toA[e];
                if (!vis[c]) { vis[c] = 1; par[c] = v; order_[tail++] = c; }
            }
        }
    }

    vector<int> vals(A.begin() + 1, A.end());
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int lo = 0, hi = (int)vals.size() - 1, best = 0;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (check(vals[mid])) { best = mid; lo = mid + 1; }
        else hi = mid - 1;
    }
    printf("%d\n", vals[best]);
    return 0;
}
