#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll INF = (ll)4e18;
int SZ;

struct Mat {
    ll v[21][21];
};

Mat mul(const Mat&A, const Mat&B){
    Mat C;
    for(int i=0;i<SZ;i++)
        for(int j=0;j<SZ;j++)
            C.v[i][j]=INF;
    for(int i=0;i<SZ;i++)
        for(int k=0;k<SZ;k++){
            if(A.v[i][k]==INF) continue;
            for(int j=0;j<SZ;j++){
                if(B.v[k][j]==INF) continue;
                ll t=A.v[i][k]+B.v[k][j];
                if(t<C.v[i][j]) C.v[i][j]=t;
            }
        }
    return C;
}

int main(){
    int n; ll m;
    if(!(cin>>n>>m)) return 0;
    vector<ll> a(n), b(n);
    for(int i=0;i<n;i++) cin>>a[i];
    for(int i=0;i<n;i++) cin>>b[i];
    SZ = n+1;
    Mat M;
    for(int s=0;s<SZ;s++){
        vector<ll> dp(SZ, INF), ndp(SZ, INF);
        dp[s]=0;
        for(int k=0;k<n;k++){
            for(int i=0;i<SZ;i++) ndp[i]=INF;
            for(int bal=0;bal<SZ;bal++){
                if(dp[bal]==INF) continue;
                if(bal+1<SZ){
                    ll t=dp[bal]+a[k];
                    if(t<ndp[bal+1]) ndp[bal+1]=t;
                }
                if(bal>=1){
                    ll t=dp[bal]+b[k];
                    if(t<ndp[bal-1]) ndp[bal-1]=t;
                }
            }
            dp=ndp;
        }
        for(int j=0;j<SZ;j++) M.v[s][j]=dp[j];
    }
    // identity
    Mat R;
    for(int i=0;i<SZ;i++)
        for(int j=0;j<SZ;j++)
            R.v[i][j] = (i==j)?0:INF;
    ll e=m;
    Mat base=M;
    while(e>0){
        if(e&1) R=mul(R,base);
        base=mul(base,base);
        e>>=1;
    }
    cout << R.v[0][0] << endl;
    return 0;
}
