#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
ll n;
const int S=6;
struct M{ ll a[S][S]; };
M mul(const M&A,const M&B){
    M C;
    for(int i=0;i<S;i++)for(int j=0;j<S;j++){
        ll s=0;
        for(int k=0;k<S;k++){
            s += (__int128)A.a[i][k]*B.a[k][j] % n;
            if(s>=(ll)4e18) s%=n;
        }
        C.a[i][j]=s%n;
    }
    return C;
}
int main(){
    ll sx,sy,dx,dy,t;
    cin>>n>>sx>>sy>>dx>>dy>>t;
    M T;
    for(int i=0;i<S;i++)for(int j=0;j<S;j++)T.a[i][j]=0;
    // state: X,Y,dx,dy,i,1
    // X' = 2X + Y + dx + i + 2
    T.a[0][0]=2%n; T.a[0][1]=1%n; T.a[0][2]=1%n; T.a[0][4]=1%n; T.a[0][5]=2%n;
    // Y' = X + 2Y + dy + i + 2
    T.a[1][0]=1%n; T.a[1][1]=2%n; T.a[1][3]=1%n; T.a[1][4]=1%n; T.a[1][5]=2%n;
    // dx' = X+Y+dx+i+2
    T.a[2][0]=1%n; T.a[2][1]=1%n; T.a[2][2]=1%n; T.a[2][4]=1%n; T.a[2][5]=2%n;
    // dy' = X+Y+dy+i+2
    T.a[3][0]=1%n; T.a[3][1]=1%n; T.a[3][3]=1%n; T.a[3][4]=1%n; T.a[3][5]=2%n;
    // i' = i+1
    T.a[4][4]=1%n; T.a[4][5]=1%n;
    // 1'=1
    T.a[5][5]=1%n;
    M R;
    for(int i=0;i<S;i++)for(int j=0;j<S;j++)R.a[i][j]=(i==j)?(1%n):0;
    ll e=t;
    while(e>0){
        if(e&1) R=mul(R,T);
        T=mul(T,T);
        e>>=1;
    }
    ll v[S];
    v[0]=(sx-1)%n;
    v[1]=(sy-1)%n;
    v[2]=((dx%n)+n)%n;
    v[3]=((dy%n)+n)%n;
    v[4]=0;
    v[5]=1%n;
    ll r[S];
    for(int i=0;i<S;i++){
        ll s=0;
        for(int k=0;k<S;k++){
            s += (__int128)R.a[i][k]*v[k]%n;
            if(s>=(ll)4e18) s%=n;
        }
        r[i]=s%n;
    }
    cout<<r[0]+1<<" "<<r[1]+1<<endl;
    return 0;
}
