        for(int i=1;i<=n;i++) if(f[i]==1){A[i]=1; st.push_back(i);}
        while(!st.empty()){
            int v=st.back(); st.pop_back();
            for(int e=hd[v];e!=-1;e=nxt[e]){
                int u=to[e];
                if(!A[u] && f[u]!=1){A[u]=1; st.push_back(u);}
            }
        }
    }
    {
        vector<int> st;
        for(int i=1;i<=n;i++) if(f[i]==2){B[i]=1; st.push_back(i);}
