#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,m;
    cin>>n>>m;
    if(m>n) swap(n,m);
    int full=(1<<m)-1;
    const int INF=1e9;
    vector<vector<int>> dp(1<<m, vector<int>(1<<m, INF)), ndp;
    auto spread=[&](int mask){ return (mask | (mask<<1) | (mask>>1)) & full; };
    for(int mask=0;mask<(1<<m);mask++){
        int c=__builtin_popcount(mask);
        int cov=spread(mask);
        dp[mask][cov]=min(dp[mask][cov],c);
    }
    for(int i=1;i<n;i++){
        ndp.assign(1<<m, vector<int>(1<<m, INF));
        for(int pm=0;pm<(1<<m);pm++)
            for(int pc=0;pc<(1<<m);pc++){
                if(dp[pm][pc]>=INF) continue;
                for(int cm=0;cm<(1<<m);cm++){
                    if(((pc|cm)&full)!=full) continue;
                    int ncov=(spread(cm)|pm)&full;
                    int val=dp[pm][pc]+__builtin_popcount(cm);
                    if(val<ndp[cm][ncov]) ndp[cm][ncov]=val;
                }
            }
        dp=ndp;
    }
    int best=INF;
    for(int mask=0;mask<(1<<m);mask++)
        best=min(best,dp[mask][full]);
    cout<<n*m-best<<endl;
    return 0;
}
