#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
const ll MOD = 1000000007LL;

ll pw(ll b, ll e, ll m){ ll r=1; b%=m; while(e>0){ if(e&1) r=r*b%m; b=b*b%m; e>>=1;} return r;}
ll inv(ll a){ return pw(a, MOD-2, MOD); }

int main(){
    ll n; int k;
    if(!(cin>>n>>k)) return 0;
    vector<pair<ll,int>> f;
    ll m=n;
    for(ll p=2;p*p<=m;p++){
        if(m%p==0){
            int c=0;
            while(m%p==0){ m/=p; c++; }
            f.push_back({p,c});
        }
    }
    if(m>1) f.push_back({m,1});

    // precompute inverses
    vector<ll> invs(64);
    for(int i=1;i<64;i++) invs[i]=inv((ll)i);

    ll ans=1;
    for(auto &pr : f){
        ll p = pr.first % MOD;
        int e = pr.second;
        vector<ll> dp(e+1), nd(e+1);
        ll cur=1;
        for(int j=0;j<=e;j++){ dp[j]=cur; cur=cur*p%MOD; }
        for(int step=0; step<k; step++){
            ll s=0;
            for(int j=0;j<=e;j++){
                s=(s+dp[j])%MOD;
                nd[j]=s*invs[j+1]%MOD;
            }
            dp=nd;
        }
        ans = ans * dp[e] % MOD;
    }
    cout << ans << endl;
    return 0;
}
